// ✏️ Danh sách nguồn RSS theo chủ đề — chỉ 5 chủ đề vegan. Thêm / bớt feed tùy ý.
//   include (tuỳ chọn) = regex; bài phải khớp (tiêu đề + tóm tắt) mới được lấy — dùng cho nguồn tin chung để chỉ giữ bài về vegan / động vật.
//   guide   = hướng dẫn giọng văn gửi cho Gemini.   colors = màu nền dự phòng khi bài không có ảnh.
const VEGAN_ANIMAL = 'vegan|plant-based|plant based|meat-free|dairy-free|animal|sanctuary|wildlife';
const ANIMAL_WIN = 'win|victory|ban\\b|commit|celebrat|success|rescue|sanctuary|adopt|freed|plant-based';

const TOPICS = [
  {
    id: 'vegan-mindset',
    label: 'Vegan mindset',
    guide: 'The vegan mindset: ethics, compassion for animals, motivation, staying vegan, handling social situations, the psychology of change. Thoughtful, encouraging, never preachy or shaming.',
    colors: ['#312e81', '#6366f1'],
    feeds: [
      { url: 'https://www.theguardian.com/lifeandstyle/veganism/rss' },
      { url: 'https://www.ourhenhouse.org/feed/' },
      { url: 'https://www.vegansociety.com/rss.xml' },
    ],
  },
  {
    id: 'vegan-lifestyle',
    label: 'Vegan lifestyle',
    guide: 'Everyday vegan living: food, products, fashion, travel, restaurants, tips for going and staying vegan. Practical, friendly, one clear takeaway.',
    colors: ['#14532d', '#16a34a'],
    feeds: [
      { url: 'https://plantbasednews.org/feed/' },
      { url: 'https://www.veganfoodandliving.com/feed/' },
      { url: 'https://veganuary.com/feed/' },
    ],
  },
  {
    id: 'vegan-vibes',
    label: 'Vegan vibes',
    guide: 'Uplifting vegan good news: wins for animals, new vegan launches, growth of plant-based eating, rescues and sanctuaries. Joyful, hopeful, celebratory.',
    colors: ['#a16207', '#facc15'],
    feeds: [
      { url: 'https://plantbasednews.org/feed/' },
      { url: 'https://www.veganfoodandliving.com/feed/' },
      { url: 'https://mercyforanimals.org/feed/', include: ANIMAL_WIN },
      { url: 'https://www.goodnewsnetwork.org/feed/', include: VEGAN_ANIMAL },
    ],
  },
  {
    id: 'vegan-recipe',
    label: 'Vegan recipe',
    guide: 'A vegan recipe. Mouth-watering, simple; mention the key ingredients and one thing that makes it special; invite readers to save and try it.',
    colors: ['#9a3412', '#f59e0b'],
    feeds: [
      { url: 'https://www.veganricha.com/feed/' },
      { url: 'https://veganheaven.org/feed/' },
      { url: 'https://thefullhelping.com/feed/' },
      { url: 'https://minimalistbaker.com/feed/' },
    ],
  },
  {
    id: 'animal-rights',
    label: 'Animal rights',
    guide: 'Animal-rights news: factory farming, cruelty investigations, laws, campaigns, sanctuaries. Honest but WITHOUT graphic detail; factual and compassionate, no insults; end with a constructive action (support rescues, choose cruelty-free, speak up).',
    colors: ['#7f1d1d', '#dc2626'],
    feeds: [
      { url: 'https://sentientmedia.org/feed/' },
      { url: 'https://mercyforanimals.org/feed/' },
      { url: 'https://www.farmsanctuary.org/feed/' },
      { url: 'https://animalequality.org/feed/' },
    ],
  },
];

return TOPICS.flatMap((t) =>
  t.feeds.map((f) => ({
    json: { topic: t.id, label: t.label, guide: t.guide, colors: t.colors, url: f.url, include: f.include || '' },
  })),
);

// Đọc tất cả feed song song, chọn bài MỚI NHẤT mỗi chủ đề (bỏ bài đã đăng), tìm & tải ảnh gốc của bài.
const cfg = $('Config').first().json;
const feeds = $input.all().map((i) => i.json);
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';
const MAX_AGE_MS = Number(cfg.maxAgeDays || 14) * 86400000;
const PER_TOPIC = Number(cfg.postsPerTopic || 1);
const MAX_POSTS = Number(cfg.maxPosts || 12);
const now = Date.now();

let seen = {};
try { seen = $getWorkflowStaticData('global').seen || {}; } catch (e) { /* static data unavailable */ }

// ---------- helpers ----------
const ENT = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', rsquo: '’', lsquo: '‘', ldquo: '“', rdquo: '”', hellip: '…', ndash: '–', mdash: '—' };
const decode = (s) =>
  String(s || '').replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (m, e) => {
    if (e[0] === '#') {
      const c = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      try { return String.fromCodePoint(c); } catch (x) { return m; }
    }
    return ENT[e.toLowerCase()] ?? m;
  });
const stripHtml = (h) =>
  decode(String(h || '').replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
const inner = (block, name) => {
  const m = block.match(new RegExp('<' + name + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + name + '>', 'i'));
  if (!m) return '';
  const v = m[1].trim();
  const cd = v.match(/^<!\[CDATA\[([\s\S]*?)\]\]>$/);
  return cd ? cd[1].trim() : decode(v);
};
const attrs = (s) => {
  const o = {};
  for (const m of s.matchAll(/([\w:-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g)) o[m[1].toLowerCase()] = decode(m[2] ?? m[3]);
  return o;
};
// (sandbox của Code node không có global URL nên tự xử lý chuỗi)
const hostOf = (u) => { const m = String(u).match(/^https?:\/\/([^/?#:]+)/i); return m ? m[1].replace(/^www\./i, '') : ''; };
const absUrl = (u, base) => {
  u = String(u || '').trim();
  if (/^https?:\/\//i.test(u)) return u;
  const b = String(base || '');
  const origin = (b.match(/^(https?:\/\/[^/?#]+)/i) || [])[1];
  if (!origin) return '';
  if (u.startsWith('//')) return 'https:' + u;
  if (u.startsWith('/')) return origin + u;
  return b.replace(/[?#].*$/, '').replace(/[^/]*$/, '') + u;
};
const BAD_IMG = /(gravatar|pixel|tracking|spacer|blank\.|emoji|1x1|\.gif(\?|$)|\.svg(\?|$)|\/logo|avatar|badge|favicon|doubleclick|feedburner)/i;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const toBuf = (b) => {
  if (Buffer.isBuffer(b)) return b;
  if (b && b.type === 'Buffer' && Array.isArray(b.data)) return Buffer.from(b.data);
  if (b instanceof ArrayBuffer) return Buffer.from(b);
  if (b && b.buffer instanceof ArrayBuffer) return Buffer.from(b.buffer, b.byteOffset, b.byteLength);
  return null;
};
const sniff = (b) => {
  if (!b || b.length < 12) return null;
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'image/jpeg';
  if (b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) return 'image/png';
  if (b.toString('latin1', 0, 4) === 'RIFF' && b.toString('latin1', 8, 12) === 'WEBP') return 'image/webp';
  return null;
};
const normKey = (link) => {
  const [path, query = ''] = String(link).replace(/#.*$/, '').replace(/^https?:\/\/(www\.)?/i, '').split('?');
  const q = query.split('&').filter((p) => p && !/^(utm_|fbclid|ref=|source=|at_)/i.test(p)).join('&');
  return (path.replace(/\/+$/, '') + (q ? '?' + q : '')).toLowerCase();
};
const titleKey = (t) => String(t).toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();

// ---------- parse one feed ----------
function parseFeed(xml, feed) {
  const out = [];
  for (const m of xml.matchAll(/<(item|entry)[\s>][\s\S]*?<\/\1>/gi)) {
    const block = m[0];
    const title = stripHtml(inner(block, 'title'));
    let link = stripHtml(inner(block, 'link'));
    if (!link) {
      const links = [...block.matchAll(/<link\b([^>]*)\/?>/gi)].map((x) => attrs(x[1]));
      const alt = links.find((l) => l.href && (!l.rel || l.rel === 'alternate')) || links.find((l) => l.href);
      link = alt ? alt.href : '';
    }
    if (!link) { const g = inner(block, 'guid'); if (/^https?:/i.test(g)) link = g; }
    if (!title || !/^https?:/i.test(link)) continue;
    const dateStr = inner(block, 'pubDate') || inner(block, 'published') || inner(block, 'updated') || inner(block, 'dc:date');
    const date = Date.parse(dateStr);
    const htmlBody = inner(block, 'content:encoded') || inner(block, 'content') || inner(block, 'description') || inner(block, 'summary');
    const descr = stripHtml(inner(block, 'description') || inner(block, 'summary'));
    const full = stripHtml(htmlBody);
    const summary = (full.length > descr.length ? full : descr).slice(0, 2200);

    // image candidates: media:content / thumbnail / enclosure, then <img> inside the body
    const media = [];
    for (const t of block.matchAll(/<(media:content|media:thumbnail|enclosure|itunes:image)\b([^>]*)>/gi)) {
      const a = attrs(t[2]);
      const u = a.url || a.href;
      if (!u) continue;
      const kind = (a.type || a.medium || '').toLowerCase();
      const isImg = kind.startsWith('image') || (!kind && /\.(jpe?g|png|webp)(\?|$)/i.test(u)) || /thumbnail|itunes:image/i.test(t[1]);
      if (!isImg || BAD_IMG.test(u)) continue;
      media.push({ u: absUrl(u, link), w: Number(a.width) || 0 });
    }
    media.sort((x, y) => y.w - x.w);
    const inline = [];
    for (const t of htmlBody.matchAll(/<img\b([^>]*)>/gi)) {
      const a = attrs(t[1]);
      let u = a['data-src'] || a['data-lazy-src'] || a['data-orig-file'] || '';
      if (!u && a.srcset) u = a.srcset.split(',').pop().trim().split(/\s+/)[0];
      if (!u) u = a.src || '';
      if (!u || /^data:/i.test(u) || BAD_IMG.test(u)) continue;
      if (Number(a.width) && Number(a.width) < 200) continue;
      inline.push(absUrl(u, link));
    }
    const images = [...new Set([...media.map((x) => x.u), ...inline].filter(Boolean))].slice(0, 4);

    out.push({
      topic: feed.topic, label: feed.label, guide: feed.guide, colors: feed.colors,
      title, link, date, summary, images,
      source: hostOf(link),
    });
  }
  return out;
}

// ---------- 1) fetch all feeds in parallel ----------
const feedErrors = [];
const fetched = await Promise.all(
  feeds.map(async (f) => {
    try {
      const res = await this.helpers.httpRequest({
        method: 'GET', url: f.url, timeout: 25000, encoding: 'text', returnFullResponse: true, ignoreHttpStatusErrors: true,
        headers: { 'User-Agent': UA, Accept: 'application/rss+xml, application/atom+xml, application/xml, text/xml, */*' },
      });
      if (res.statusCode >= 400) throw new Error('HTTP ' + res.statusCode);
      let items = parseFeed(String(res.body), f);
      if (f.include) { const re = new RegExp(f.include, 'i'); items = items.filter((a) => re.test(a.title + ' ' + a.summary)); }
      return items;
    } catch (e) {
      feedErrors.push(f.url + ' → ' + String(e.message).slice(0, 80));
      return [];
    }
  }),
);
if (!fetched.some((x) => x.length) && feedErrors.length === feeds.length) {
  throw new Error('Không đọc được feed nào (kiểm tra mạng của container). Ví dụ: ' + feedErrors.slice(0, 3).join(' | '));
}

// ---------- 2) pick the freshest unseen article per topic ----------
const byTopic = new Map();
for (const f of feeds) if (!byTopic.has(f.topic)) byTopic.set(f.topic, []);
fetched.flat().forEach((a) => byTopic.get(a.topic).push(a));
const topicIds = [...byTopic.keys()];
const rot = Math.floor(now / 86400000) % topicIds.length; // xoay vòng để chủ đề cuối không bị cắt khi MAX_POSTS nhỏ
const order = [...topicIds.slice(rot), ...topicIds.slice(0, rot)];

const usedKeys = new Set();
const usedTitles = new Set();
// lấy xen kẽ từng vòng (chủ đề 1, 2, …, 5, rồi lại 1, 2, …) để 2 bài cùng chủ đề không đăng liền nhau
// chủ đề nào hết bài thì các chủ đề khác lấy bù (tối đa postsPerTopic bài / chủ đề) cho đủ maxPosts
const picks = [];
for (let round = 0; round < PER_TOPIC && picks.length < MAX_POSTS; round++) {
  const before = picks.length;
  for (const topic of order) {
    if (picks.length >= MAX_POSTS) break;
    const a = byTopic.get(topic)
      .filter((a) => a.date && a.date <= now + 86400000 && now - a.date <= MAX_AGE_MS)
      .filter((a) => !seen[normKey(a.link)] && !usedKeys.has(normKey(a.link)) && !usedTitles.has(titleKey(a.title)))
      .sort((a, b) => b.date - a.date)[0];
    if (!a) continue;
    usedKeys.add(normKey(a.link));
    usedTitles.add(titleKey(a.title));
    picks.push(a);
  }
  if (picks.length === before) break; // không chủ đề nào còn bài
}
const chosen = picks.slice(0, MAX_POSTS);

// ---------- 3) find + download the article photo ----------
const download = async (url, referer) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url, timeout: 25000, encoding: 'arraybuffer', returnFullResponse: true, ignoreHttpStatusErrors: true,
      headers: { 'User-Agent': UA, Accept: 'image/avif,image/webp,image/png,image/jpeg,*/*;q=0.8', Referer: referer },
    });
    if (res.statusCode >= 400) return null;
    const buf = toBuf(res.body);
    const mime = sniff(buf);
    if (!mime || buf.length < 15000 || buf.length > 9 * 1024 * 1024) return null;
    const size = imageSize(buf) || { w: 800, h: 800 };
    return { buf, mime, w: size.w, h: size.h };
  } catch (e) { return null; }
};
// kích thước thật của ảnh (PNG / JPEG / WebP) — để loại ảnh thumbnail nhỏ, phóng lên sẽ bị mờ
const imageSize = (b) => {
  try {
    if (b[0] === 0x89 && b[1] === 0x50) return { w: b.readUInt32BE(16), h: b.readUInt32BE(20) };
    if (b[0] === 0xff && b[1] === 0xd8) {
      let o = 2;
      while (o < b.length - 9) {
        if (b[o] !== 0xff) { o++; continue; }
        const m = b[o + 1];
        if (m === 0xd8 || m === 0x01 || (m >= 0xd0 && m <= 0xd7) || m === 0xff) { o += m === 0xff ? 1 : 2; continue; }
        if (m >= 0xc0 && m <= 0xcf && m !== 0xc4 && m !== 0xc8 && m !== 0xcc) return { h: b.readUInt16BE(o + 5), w: b.readUInt16BE(o + 7) };
        o += 2 + b.readUInt16BE(o + 2);
      }
    }
    if (b.toString('latin1', 0, 4) === 'RIFF') {
      const t = b.toString('latin1', 12, 16);
      if (t === 'VP8 ') return { w: b.readUInt16LE(26) & 0x3fff, h: b.readUInt16LE(28) & 0x3fff };
      if (t === 'VP8L') { const v = b.readUInt32LE(21); return { w: (v & 0x3fff) + 1, h: ((v >> 14) & 0x3fff) + 1 }; }
      if (t === 'VP8X') return { w: 1 + b.readUIntLE(24, 3), h: 1 + b.readUIntLE(27, 3) };
    }
  } catch (e) { /* ignore */ }
  return null;
};
const ogImage = async (page) => {
  try {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: page, timeout: 20000, encoding: 'text', returnFullResponse: true, ignoreHttpStatusErrors: true,
      headers: { 'User-Agent': UA, Accept: 'text/html,*/*' },
    });
    if (res.statusCode >= 400) return '';
    const html = String(res.body).slice(0, 400000);
    for (const t of html.matchAll(/<meta\b([^>]*)>/gi)) {
      const a = attrs(t[1]);
      const k = (a.property || a.name || '').toLowerCase();
      if ((k === 'og:image' || k === 'og:image:url' || k === 'twitter:image' || k === 'twitter:image:src') && a.content) return absUrl(a.content, page);
    }
  } catch (e) { /* ignore */ }
  return '';
};

const out = [];
for (const a of chosen) {
  // Lấy ảnh lớn nhất tìm được. Ảnh nhỏ hơn MIN_W bị bỏ (phóng lên 1080px sẽ quá mờ) → workflow dùng nền gradient.
  const MIN_W = 500, GOOD_W = 1000;
  // WordPress hay đặt hậu tố kích thước (vd. -150x225.jpg): bỏ đi sẽ ra ảnh gốc
  const variants = (u) => { const s = u.replace(/-\d{2,4}x\d{2,4}(\.(?:jpe?g|png|webp))(\?.*)?$/i, '$1$2'); return s !== u ? [s, u] : [u]; };
  let img = null, imgUrl = '';
  const consider = async (u) => {
    const d = await download(u, a.link);
    if (d && (!img || d.w * d.h > img.w * img.h)) { img = d; imgUrl = u; }
  };
  for (const u of a.images.flatMap(variants)) { await consider(u); if (img && img.w >= GOOD_W) break; }
  if (!img || img.w < GOOD_W) {
    const og = await ogImage(a.link);
    if (og && !BAD_IMG.test(og)) await consider(og);
  }
  if (img && img.w < MIN_W) { img = null; imgUrl = ''; }
  const json = {
    topic: a.topic, label: a.label, guide: a.guide, colors: a.colors,
    title: a.title, link: a.link, source: a.source, pubDate: new Date(a.date).toISOString(), summary: a.summary,
    seenKey: normKey(a.link), imageUrl: imgUrl, imageWidth: img ? img.w : 0, hasPhoto: !!img,
  };
  const item = { json };
  if (img) {
    const ext = img.mime === 'image/png' ? 'png' : img.mime === 'image/webp' ? 'webp' : 'jpg';
    item.binary = { source: await this.helpers.prepareBinaryData(img.buf, 'source.' + ext, img.mime) };
  }
  out.push(item);
}
if (feedErrors.length) console.log('Feeds lỗi (' + feedErrors.length + '): ' + feedErrors.join(' ; '));
console.log('Chọn ' + out.length + ' bài, ' + out.filter((o) => o.json.hasPhoto).length + ' bài có ảnh gốc.');
return out;

// Gemini viết: (1) câu chữ in trên ảnh, (2) caption đăng Facebook, (3) hashtag, 
const cfg = $('Config').first().json;
const API_KEY = String(cfg.geminiApiKey || '').trim();
if (!API_KEY || /PASTE|YOUR_/i.test(API_KEY)) throw new Error('Chưa có Gemini API key: điền vào node "Config" (geminiApiKey).');
const BASE = String(cfg.geminiBaseUrl || 'https://generativelanguage.googleapis.com').replace(/\/+$/, '');
const csv = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean);
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const LANGUAGE = String(cfg.captionLanguage || 'Vietnamese');

// Gọi generateContent, tự thử lần lượt các model; tự chờ khi bị 429 tạm thời; báo "quotaZero" khi gói free không có hạn mức.
const callGemini = async (models, buildBody, opts = {}) => {
  const started = Date.now();
  const deadline = opts.deadlineMs || 200000;
  let lastErr = null;
  let allQuotaZero = true;
  for (const model of models) {
    for (let attempt = 0; attempt < 3; attempt++) {
      if (Date.now() - started > deadline) break;
      let res;
      try {
        res = await this.helpers.httpRequest({
          method: 'POST',
          url: BASE + '/v1beta/models/' + encodeURIComponent(model) + ':generateContent',
          headers: { 'x-goog-api-key': API_KEY, 'Content-Type': 'application/json' },
          body: buildBody(model), json: true, timeout: opts.timeout || 90000,
          ignoreHttpStatusErrors: true, returnFullResponse: true,
        });
      } catch (e) {
        lastErr = new Error(model + ': ' + e.message);
        allQuotaZero = false;
        await sleep(3000);
        continue;
      }
      const status = res.statusCode;
      const data = res.body;
      if (status >= 200 && status < 300) return { model, data };
      const msg = String((data && data.error && data.error.message) || JSON.stringify(data) || '').split('\n')[0].slice(0, 220);
      const full = String((data && data.error && data.error.message) || '');
      lastErr = new Error(model + ' → HTTP ' + status + ': ' + msg);
      if (status === 401 || status === 403 || (status === 400 && /API key/i.test(msg))) { lastErr.fatal = true; throw lastErr; }
      if (status === 429) {
        if (/limit:\s*0\b/.test(full)) break; // gói hiện tại không có hạn mức cho model này → thử model khác
        allQuotaZero = false;
        const det = ((data.error && data.error.details) || []).find((d) => d.retryDelay);
        const wait = det ? parseFloat(det.retryDelay) : 12;
        if (wait > 90) break; // hết hạn mức theo ngày → model khác
        await sleep((wait + 1) * 1000);
        continue;
      }
      allQuotaZero = false;
      if (status >= 500) { await sleep(4000 * (attempt + 1)); continue; }
      break; // 400 / 404 → model khác
    }
  }
  const err = lastErr || new Error('Gemini request failed');
  if (allQuotaZero) err.quotaZero = true;
  throw err;
};


const TEXT_MODELS = csv(cfg.textModels);
const SYSTEM = [
  'You are the social-media editor of a Facebook page about compassionate, plant-based, healthy living.',
  'Voice: warm, calm, hopeful and intelligent. Never preachy, shaming or sensational.',
  'Rules: use ONLY facts that appear in the article excerpt; never invent statistics, quotes or names.',
  'For health topics write "research suggests" / "a study found" and never promise cures or give medical advice.',
  'Never describe graphic violence or gore. Do not insult people or brands. Credit the source by name.',
  'Write every user-facing text in ' + LANGUAGE + ' (keep all diacritics correct). Use only real ' + LANGUAGE + ' words: never mix in words from any other language (except proper names and widely used English terms).',
].join('\n');

const extractJson = (text) => {
  const t = String(text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  try { return JSON.parse(t); } catch (e) { /* try to find an object inside */ }
  const m = t.match(/\{[\s\S]*\}/);
  if (m) { try { return JSON.parse(m[0]); } catch (e) { /* fallthrough */ } }
  throw new Error('Gemini không trả về JSON hợp lệ: ' + t.slice(0, 120));
};

const out = [];
const PHOTO_CHECK = cfg.photoCheck !== false && String(cfg.photoCheck).toLowerCase() !== 'false';
const allItems = $input.all();
for (let idx = 0; idx < allItems.length; idx++) {
  const item = allItems[idx];
  const j = item.json;
  try {
    let photo = null;
    if (PHOTO_CHECK && item.binary && item.binary.source) {
      const pb = await this.helpers.getBinaryDataBuffer(idx, 'source');
      if (pb && pb.length < 6 * 1024 * 1024) photo = { mime: item.binary.source.mimeType || 'image/jpeg', b64: pb.toString('base64') };
    }
    const prompt = [
      'TOPIC: ' + j.label,
      'TOPIC GUIDE: ' + j.guide,
      'SOURCE: ' + j.source,
      'TITLE: ' + j.title,
      'PUBLISHED: ' + j.pubDate,
      'ARTICLE EXCERPT:',
      j.summary || '(no excerpt available - rely on the title only and stay general)',
      '',
      'Return ONE JSON object with exactly these keys:',
      '"imageText": a news-style headline to print ON the image, 8-16 words, natural sentence case, informative and engaging (like a Facebook news card), no emojis, no hashtags, no quotation marks, no website names or URLs, in ' + LANGUAGE + '.',
      '"fbCaption": the Facebook post text in ' + LANGUAGE + ': a strong first-line hook, 2-4 short paragraphs (70-150 words in total), at most 3 emojis, and a closing question or gentle call to action. Do NOT include hashtags, the URL or a source line (they are added automatically). You may mention the source name naturally inside the text.',
      '"hashtags": array of 5-8 relevant hashtags WITHOUT the # symbol, no spaces inside each one, in ' + LANGUAGE + '.',
      ...(photo ? ['"photoFits": true or false. A photo from the article is attached. Answer true ONLY if it is sharp, looks professional and clearly illustrates the topic "' + j.label + '" and this story (for example plant-based food, plants, animals, nature, or the real subject of the article). Answer false if it is blurry, tiny, a screenshot, a logo, a chart, contains lots of text, shows mainly a person or a close-up face, or looks like generic stock imagery unrelated to the story.'] : []),
    ].join('\n');
    const ask = (usePhoto) => callGemini(TEXT_MODELS, () => ({
      systemInstruction: { parts: [{ text: SYSTEM }] },
      contents: [{ role: 'user', parts: [{ text: prompt }, ...(usePhoto ? [{ inlineData: { mimeType: photo.mime, data: photo.b64 } }] : [])] }],
      generationConfig: { responseMimeType: 'application/json' },
    }), { timeout: 80000, deadlineMs: 200000 });
    let res;
    try { res = await ask(!!photo); } catch (e) { if (e.fatal || !photo) throw e; photo = null; res = await ask(false); }
    const { model, data } = res;
    const parts = (data.candidates && data.candidates[0] && data.candidates[0].content && data.candidates[0].content.parts) || [];
    const text = parts.filter((p) => p.text && !p.thought).map((p) => p.text).join('');
    const r = extractJson(text);
    let imageText = String(r.imageText || '').replace(/["“”]/g, '').replace(/\s+/g, ' ').trim();
    imageText = imageText.charAt(0).toUpperCase() + imageText.slice(1);
    const fbCaption = String(r.fbCaption || '').trim();
    if (!imageText || !fbCaption) throw new Error('Gemini thiếu imageText/fbCaption');
    const hashtags = (Array.isArray(r.hashtags) ? r.hashtags : String(r.hashtags || '').split(/[\s,]+/))
      .map((h) => String(h).replace(/^#+/, '').replace(/[^\p{L}\p{N}_]/gu, ''))
      .filter(Boolean).slice(0, 8);
    const keepPhoto = !photo || r.photoFits !== false;
    out.push({
      json: { ...j, imageText, fbCaption, hashtags, textModel: model, photoRejected: !keepPhoto, hasPhoto: keepPhoto && j.hasPhoto },
      binary: keepPhoto ? item.binary : undefined,
    });
  } catch (e) {
    if (e.fatal) throw new Error('Gemini từ chối API key: ' + e.message);
    out.push({ json: { ...j, error: 'caption: ' + e.message }, binary: item.binary });
  }
}
return out;

// Tạo ảnh bài đăng từ ảnh gốc của bài (bài không có ảnh → nền gradient theo màu chủ đề), rồi node "Add text to image" ghép chữ lên.
const cfg = $('Config').first().json;
const BRAND = String(cfg.brandName || '').trim().toUpperCase() || ' ';
const TAG = () => String(cfg.labelText || 'NEWS').trim().toUpperCase() || 'NEWS';

// ---- image utils ----
const sniff = (b) => {
  if (!b || b.length < 12) return null;
  if (b[0] === 0xff && b[1] === 0xd8 && b[2] === 0xff) return 'image/jpeg';
  if (b[0] === 0x89 && b[1] === 0x50 && b[2] === 0x4e && b[3] === 0x47) return 'image/png';
  if (b.toString('latin1', 0, 4) === 'RIFF' && b.toString('latin1', 8, 12) === 'WEBP') return 'image/webp';
  return null;
};
const extOf = (mime) => (mime === 'image/png' ? 'png' : mime === 'image/webp' ? 'webp' : 'jpg');
const imageSize = (b) => {
  try {
    if (b[0] === 0x89 && b[1] === 0x50) return { w: b.readUInt32BE(16), h: b.readUInt32BE(20) };
    if (b[0] === 0xff && b[1] === 0xd8) {
      let o = 2;
      while (o < b.length - 9) {
        if (b[o] !== 0xff) { o++; continue; }
        const m = b[o + 1];
        if (m === 0xd8 || m === 0x01 || (m >= 0xd0 && m <= 0xd7) || m === 0xff) { o += m === 0xff ? 1 : 2; continue; }
        if (m >= 0xc0 && m <= 0xcf && m !== 0xc4 && m !== 0xc8 && m !== 0xcc) return { h: b.readUInt16BE(o + 5), w: b.readUInt16BE(o + 7) };
        o += 2 + b.readUInt16BE(o + 2);
      }
    }
    if (b.toString('latin1', 0, 4) === 'RIFF') {
      const t = b.toString('latin1', 12, 16);
      if (t === 'VP8 ') return { w: b.readUInt16LE(26) & 0x3fff, h: b.readUInt16LE(28) & 0x3fff };
      if (t === 'VP8L') { const v = b.readUInt32LE(21); return { w: (v & 0x3fff) + 1, h: ((v >> 14) & 0x3fff) + 1 }; }
      if (t === 'VP8X') return { w: 1 + b.readUIntLE(24, 3), h: 1 + b.readUIntLE(27, 3) };
    }
  } catch (e) { /* ignore */ }
  return null;
};

// 8x10 gradient PNG (không cần thư viện) — node Edit Image sẽ phóng to thành nền 1080x1350.
const CRC_T = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
const crc32 = (buf) => { let c = 0xffffffff; for (const x of buf) c = CRC_T[(c ^ x) & 0xff] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };
const adler32 = (buf) => { let a = 1, b = 0; for (const x of buf) { a = (a + x) % 65521; b = (b + a) % 65521; } return ((b << 16) | a) >>> 0; };
const be32 = (n) => { const b = Buffer.alloc(4); b.writeUInt32BE(n >>> 0); return b; };
const chunk = (type, data) => { const td = Buffer.concat([Buffer.from(type, 'ascii'), data]); return Buffer.concat([be32(data.length), td, be32(crc32(td))]); };
const gradientPng = (c1, c2) => {
  const w = 8, h = 10;
  const hex = (c) => [1, 3, 5].map((i) => parseInt(c.slice(i, i + 2), 16));
  const A = hex(c1), B = hex(c2);
  const stride = 1 + w * 3;
  const raw = Buffer.alloc(stride * h);
  for (let y = 0; y < h; y++) {
    const px = A.map((v, i) => Math.round(v + (B[i] - v) * (y / (h - 1))));
    for (let x = 0; x < w; x++) raw.set(px, y * stride + 1 + x * 3);
  }
  const L = raw.length;
  const z = Buffer.concat([Buffer.from([0x78, 0x01, 0x01, L & 255, L >> 8, ~L & 255, (~L >> 8) & 255]), raw, be32(adler32(raw))]);
  const ihdr = Buffer.concat([be32(w), be32(h), Buffer.from([8, 2, 0, 0, 0])]);
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk('IHDR', ihdr), chunk('IDAT', z), chunk('IEND', Buffer.alloc(0))]);
};

// Lớp tối 1080x1350 (PNG palette + tRNS, mỗi dòng 1 độ trong suốt) — node Edit Image ghép lên ảnh, chuyển mượt không bị sọc.
const zStore = (raw) => {
  const parts = [Buffer.from([0x78, 0x01])];
  for (let o = 0; o < raw.length; o += 65535) {
    const L = Math.min(65535, raw.length - o);
    parts.push(Buffer.from([o + L >= raw.length ? 1 : 0, L & 255, L >> 8, ~L & 255, (~L >> 8) & 255]), raw.subarray(o, o + L));
  }
  parts.push(be32(adler32(raw)));
  return Buffer.concat(parts);
};
const ease = (t) => t * t * (3 - 2 * t);
const shadePng = (w, h, alphaAt) => {
  const plte = Buffer.alloc(256 * 3), trns = Buffer.alloc(256);
  for (let i = 0; i < 256; i++) trns[i] = i;
  const raw = Buffer.alloc((w + 1) * h);
  for (let y = 0; y < h; y++) raw.fill(Math.max(0, Math.min(255, Math.round(alphaAt(y)))), y * (w + 1) + 1, (y + 1) * (w + 1));
  const ihdr = Buffer.concat([be32(w), be32(h), Buffer.from([8, 3, 0, 0, 0])]);
  return Buffer.concat([Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]), chunk('IHDR', ihdr), chunk('PLTE', plte), chunk('tRNS', trns), chunk('IDAT', zStore(raw)), chunk('IEND', Buffer.alloc(0))]);
};
// trên: tối nhẹ sau tên trang; dưới: tối dần từ trên nhãn xuống, đậm hẳn sau mép trên tiêu đề
const shadeFor = (cp) => shadePng(W, H, (y) => Math.max(
  y < 230 ? 150 * ease(1 - y / 230) : 0,
  y <= cp.shadeFrom ? 0 : y >= cp.shadeTo ? 232 : 232 * ease((y - cp.shadeFrom) / (cp.shadeTo - cp.shadeFrom)),
));

const wrap = (text, maxChars) => {
  const lines = [];
  let cur = '';
  for (const w of String(text).split(/\s+/)) {
    if (cur && (cur + ' ' + w).length > maxChars) { lines.push(cur); cur = w; } else cur = cur ? cur + ' ' + w : w;
  }
  if (cur) lines.push(cur);
  // tránh dòng cuối chỉ có 1 chữ: kéo chữ cuối của dòng trước xuống
  const n = lines.length;
  if (n >= 2 && !/\s/.test(lines[n - 1])) {
    const prev = lines[n - 2].split(' ');
    if (prev.length >= 3) { lines[n - 1] = prev.pop() + ' ' + lines[n - 1]; lines[n - 2] = prev.join(' '); }
  }
  return lines;
};

// Bố cục kiểu bài tin tức: ảnh 1080x1350 (4:5) phủ kín, tên trang ở góc trên, nhãn chủ đề, tiêu đề lớn (dòng cuối tô vàng),
// lớp tối dần từ dưới lên. Mọi toạ độ tính ở đây rồi node "Add text to image" chỉ việc vẽ.
const W = 1080, H = 1350, M = 64, MAX_LINES = 6;
const composeParams = (text, w, h, tag, brand) => {
  const sc = Math.max(W / w, H / h);
  const sw = Math.max(W, Math.round(w * sc));
  const sh = Math.max(H, Math.round(h * sc));
  const len = text.length;
  let fs = len <= 60 ? 66 : len <= 90 ? 60 : len <= 120 ? 54 : 48;
  let lines;
  for (;;) {
    lines = wrap(text, Math.floor((W - 2 * M) / (fs * 0.6)));
    if (lines.length <= MAX_LINES || fs <= 34) break;
    fs -= 4;
  }
  lines = lines.slice(0, MAX_LINES);
  const lineH = Math.round(fs * 1.22);
  const headTop = H - 72 - lines.length * lineH;
  const labelFs = 34, labelH = 60;
  const labelW = Math.round(tag.length * labelFs * 0.74 + 44);
  const labelY = headTop - 30 - labelH;
  const gradStart = labelY - 320;
  return {
    resizeW: W, resizeH: H, cropW: W, cropH: H,
    cropX: Math.floor((sw - W) / 2), cropY: Math.floor((sh - H) * 0.35),
    shadeFrom: gradStart, shadeTo: headTop - 30,
    endX: W + 80, endY: H + 80,
    // GraphicsMagick đặt chữ theo đường baseline: baseline = mép trên chữ + ~0.74 * cỡ chữ
    brand: { text: brand, x: M, y: 48 + Math.round(0.74 * 32), fs: 32 },
    label: { text: tag, x: M, y: labelY, w: labelW, h: labelH, tx: M + 22, ty: labelY + Math.round((labelH + 0.72 * labelFs) / 2), fs: labelFs },
    lines: Array.from({ length: MAX_LINES }, (_, i) => lines[i]
      ? { text: lines[i], y: headTop + i * lineH + Math.round(0.74 * fs), fs, color: lines.length >= 2 && i === lines.length - 1 ? '#FFD84D' : '#FFFFFF' }
      : { text: '.', y: 5000, fs, color: '#FFFFFF' }),
  };
};

// ---- main ----
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const j = item.json;
  if (j.error) { out.push(item); continue; }

  let base = null;
  let kind = 'article-photo';
  if (item.binary && item.binary.source) {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'source');
    base = { buf, mime: item.binary.source.mimeType || sniff(buf) || 'image/jpeg' };
  }
  if (!base) {
    const c = Array.isArray(j.colors) && j.colors.length === 2 ? j.colors : ['#14532d', '#16a34a'];
    base = { buf: gradientPng(c[0], c[1]), mime: 'image/png' };
    kind = 'gradient';
  }
  const size = imageSize(base.buf) || { w: 1080, h: 810 };
  const compose = composeParams(j.imageText, size.w, size.h, TAG(), BRAND);
  out.push({
    json: { ...j, imageSource: kind, compose },
    binary: {
      photo: await this.helpers.prepareBinaryData(base.buf, 'photo.' + extOf(base.mime), base.mime),
      shade: await this.helpers.prepareBinaryData(shadeFor(compose), 'shade.png', 'image/png'),
    },
  });
}
return out;

// Mỗi bài → 2 file: <tên>.png (ảnh có chữ) + <tên>.txt (caption đăng Facebook).
const cfg = $('Config').first().json;
const DIR = String(cfg.outputDir || '/files/output').replace(/[\\/]+$/, '');

let stamp;
try { stamp = $now.toFormat('yyyy-LL-dd_HHmm'); } catch (e) { stamp = new Date().toISOString().slice(0, 16).replace('T', '_').replace(':', ''); }
const slug = (s) => String(s).normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/gi, 'd').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 50) || 'post';

let sd = null;
try { sd = $getWorkflowStaticData('global'); } catch (e) { /* static data unavailable */ }

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const image = item.binary && item.binary.image;
  if (j.error || !j.fbCaption) {
    out.push({ json: { error: j.error || 'thiếu caption', title: j.title, link: j.link } });
    continue;
  }
  const base = stamp + '_' + j.topic + '_' + slug(j.title);
  const sourceLabel = /vi/i.test(String(cfg.captionLanguage || '')) ? 'Nguồn' : 'Source';
  const hashtags = (j.hashtags || []).map((h) => '#' + h).join(' ');
  const caption = [j.fbCaption.trim(), hashtags, sourceLabel + ': ' + j.link].filter(Boolean).join('\n\n') + '\n';

  if (image) {
    const mime = image.mimeType || 'image/png';
    const ext = mime === 'image/jpeg' ? 'jpg' : mime === 'image/webp' ? 'webp' : 'png';
    out.push({
      json: { filePath: DIR + '/' + base + '.' + ext, kind: 'image', topic: j.topic, title: j.title, imageSource: j.imageSource, fbStatus: j.fbStatus || '', fbScheduledAt: j.fbScheduledAt || '', fbScheduledAtVN: j.fbScheduledAtVN || '' },
      binary: { data: image },
    });
  }
  out.push({
    json: { filePath: DIR + '/' + base + '.txt', kind: 'caption', topic: j.topic, title: j.title },
    binary: { data: await this.helpers.prepareBinaryData(Buffer.from(caption, 'utf8'), base + '.txt', 'text/plain') },
  });

  if (sd) { // nhớ bài đã đăng để lần chạy sau không lặp lại
    sd.seen = sd.seen || {};
    sd.seen[j.seenKey] = Date.now();
    for (const k of Object.keys(sd.seen)) if (Date.now() - sd.seen[k] > 90 * 86400000) delete sd.seen[k];
  }
}
return out;

// Tổng kết sau khi xử lý xong tất cả bài.
const all = $input.all().map((i) => i.json);
const failed = all.filter((x) => x.error);
const files = all.filter((x) => !x.error && x.filePath);
const cfg = $('Config').first().json;
return [{
  json: {
    outputDir: cfg.outputDir,
    filesSaved: files.length,
    postsFailed: failed.length,
    images: files.filter((f) => f.kind === 'image').length,
    captions: files.filter((f) => f.kind === 'caption').length,
    errors: failed.map((f) => (f.title ? f.title + ' — ' : '') + f.error),
    imageSources: files.filter((f) => f.kind === 'image').reduce((o, f) => ((o[f.imageSource] = (o[f.imageSource] || 0) + 1), o), {}),
    facebook: files.filter((f) => f.kind === 'image').map((f) => (f.fbStatus === 'scheduled' ? f.fbScheduledAt + ' (VN ' + f.fbScheduledAtVN + ')' : f.fbStatus) + ' — ' + f.title),
    files: files.map((f) => f.filePath),
  },
}];

// Chuẩn bị bài hẹn giờ cho Facebook Page: tính giờ đăng + caption. Node "Facebook: schedule post" (HTTP Request) sẽ upload.
// Các bài của một lần chạy được chia đều từ fbStartTime đến fbEndTime (giờ fbTimezone) của ngày kế tiếp còn kịp.
const cfg = $('Config').first().json;
const PAGE_ID = String(cfg.fbPageId || '').trim();
const TOKEN = String(cfg.fbPageToken || '').trim();
const TZ = String(cfg.fbTimezone || 'America/New_York');

const item = $input.first();
const j = item.json;
const skip = !PAGE_ID || !TOKEN || /PASTE|YOUR_/i.test(TOKEN) || !(item.binary && item.binary.image);

// ---- giờ đăng ----
const hm = (s, d) => { const m = String(s || d).match(/^(\d{1,2}):(\d{2})$/); return m ? { hour: +m[1], minute: +m[2] } : hm(d, d); };
const total = Math.max(1, $('Fetch RSS & pick articles').all().length);
const slot = $runIndex; // vòng lặp xử lý 1 bài / lần → lần thứ mấy tới node này = bài thứ mấy được đăng
const now = DateTime.now().setZone(TZ);
let day = now.startOf('day');
const startOf = (d) => d.set(hm(cfg.fbStartTime, '08:00'));
if (startOf(day) < now.plus({ minutes: 20 })) day = day.plus({ days: 1 });
const start = startOf(day);
let end = day.set(hm(cfg.fbEndTime, '20:00'));
if (end <= start) end = end.plus({ days: 1 });
const step = total > 1 ? (end - start) / (total - 1) : 0;
const when = start.plus({ milliseconds: Math.round(step * Math.min(slot, total - 1)) }).startOf('minute');

// ---- caption giống file .txt ----
const sourceLabel = /vi/i.test(String(cfg.captionLanguage || '')) ? 'Nguồn' : 'Source';
const hashtags = (j.hashtags || []).map((h) => '#' + h).join(' ');
const message = [String(j.fbCaption || '').trim(), hashtags, sourceLabel + ': ' + j.link].filter(Boolean).join('\n\n');

return [{
  json: {
    ...j,
    fb: {
      skip,
      url: 'https://graph.facebook.com/' + String(cfg.fbGraphVersion || 'v24.0') + '/' + encodeURIComponent(PAGE_ID) + '/photos',
      // ảnh tải lên ẩn tạm (photos) rồi tạo BÀI VIẾT (feed) gắn ảnh đó → hiện trên dòng thời gian Page (đăng thẳng /photos chỉ thành ảnh trong album)
      feedUrl: 'https://graph.facebook.com/' + String(cfg.fbGraphVersion || 'v24.0') + '/' + encodeURIComponent(PAGE_ID) + '/feed',
      token: TOKEN,
      message,
      time: String(Math.floor(when.toSeconds())),
      at: when.toFormat('yyyy-LL-dd HH:mm') + ' ' + when.offsetNameShort,
      atVN: when.setZone('Asia/Ho_Chi_Minh').toFormat('yyyy-LL-dd HH:mm'),
    },
  },
  binary: item.binary,
}];

// Gộp kết quả Facebook vào bài (giữ ảnh) để lưu file + báo cáo ở Summary.
const p = $('Prepare Facebook post').first();
const { fb, ...j } = p.json;
let r = $input.first().json || {};
// bước tải ảnh lỗi → báo lỗi đó (bước tạo bài sẽ chỉ báo thiếu ảnh)
try { const u = $('Facebook: upload photo').first().json || {}; if (!fb.skip && !u.id) r = u; } catch (e) { /* nhánh bỏ qua đăng FB */ }
const id = r.post_id || r.id;
let fbStatus;
if (fb.skip) fbStatus = 'skipped (chưa có fbPageId / fbPageToken)';
else if (id) fbStatus = 'scheduled';
else {
  const e = r.error || {};
  const msg = (e.description || e.message || (typeof e === 'string' ? e : '') || JSON.stringify(r)).toString();
  fbStatus = 'error: ' + msg.slice(0, 250);
}
return [{
  json: { ...j, fbStatus, fbScheduledAt: fb.at, fbScheduledAtVN: fb.atVN, fbPostId: id || '' },
  binary: p.binary,
}];
